import { Link } from 'react-router-dom';
import { motion, useReducedMotion } from 'motion/react';
import type { Listing } from '../types';

export function CatalogProperty({ listing, index, favorite, onToggleFavorite }: { listing: Listing; index: number; favorite: boolean; onToggleFavorite: (id: string) => void }) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.article className={`catalog-property ${index % 2 === 1 ? 'catalog-property--reverse' : ''}`} initial={reduceMotion ? false : { opacity: 0, y: 50, rotate: index % 2 === 0 ? -1 : 1 }} whileInView={{ opacity: 1, y: 0, rotate: 0 }} viewport={{ once: true, amount: 0.18 }} transition={{ duration: 0.55, ease: [0.16, 1, 0.3, 1] }}>
      <figure><img src={`/assets/listings/${listing.id}.webp`} alt={listing.alt} width="900" height="1200" loading="lazy" decoding="async" /></figure>
      <div className="catalog-property__content"><p className="eyebrow">{listing.neighborhood} · {listing.type} · {listing.id}</p><h2>{listing.title}</h2><p className="catalog-property__location">{listing.location} · {listing.area}</p><p className="catalog-property__description">{listing.description}</p><p className="catalog-property__price">{listing.price}</p><div className="catalog-property__actions"><Link className="text-link" to={`/imoveis/${listing.id}`}>Ver este endereço <span aria-hidden="true">↗</span></Link><button type="button" aria-pressed={favorite} aria-label={`${favorite ? 'Remover' : 'Guardar'} ${listing.title}`} onClick={() => onToggleFavorite(listing.id)}>{favorite ? '✓ Guardado' : '+ Guardar'}</button></div></div>
    </motion.article>
  );
}
