import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { motion, useReducedMotion, useScroll, useTransform } from 'motion/react';
import { findListing } from '../data/listings';

const cards = [
  { id: 'CB-009', className: 'hero-photo--one', caption: 'Copacabana · vista para o mar', position: '01', rotation: -7 },
  { id: 'CB-006', className: 'hero-photo--two', caption: 'Ipanema · viver o bairro', position: '02', rotation: 7 },
  { id: 'CB-017', className: 'hero-photo--three', caption: 'Leblon · novos endereços', position: '03', rotation: 5 },
] as const;

export function HeroCollage() {
  const hero = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const [desktop, setDesktop] = useState(false);
  const { scrollYProgress } = useScroll({ target: hero, offset: ['start start', 'end start'] });
  const yOne = useTransform(scrollYProgress, [0, 1], [0, 240]);
  const yTwo = useTransform(scrollYProgress, [0, 1], [0, 310]);
  const yThree = useTransform(scrollYProgress, [0, 1], [0, -150]);
  const yFour = useTransform(scrollYProgress, [0, 1], [0, -210]);
  const copyY = useTransform(scrollYProgress, [0, 1], [0, 110]);
  const copyScale = useTransform(scrollYProgress, [0, 1], [1, 0.9]);
  const photoY = [yOne, yTwo, yThree];
  const parallax = desktop && !reduceMotion;

  useEffect(() => {
    const query = window.matchMedia('(min-width: 901px)');
    const update = () => setDesktop(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);

  return (
    <div ref={hero} className="hero-collage">
      <motion.div className="hero-collage__scroll" style={parallax ? { y: copyY, scale: copyScale } : {}}>
        <div className="hero-collage__copy">
          <motion.p className="hero-kicker" initial={reduceMotion ? false : { opacity: 0, y: -18 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.45 }}><span aria-hidden="true" />Copacabana · Rio de Janeiro · desde 1973</motion.p>
          <h1 id="hero-title">
            <motion.span initial={reduceMotion ? false : { opacity: 0, y: 70, rotate: 2 }} animate={{ opacity: 1, y: 0, rotate: 0 }} transition={{ duration: 0.6, delay: 0.08, ease: [0.16, 1, 0.3, 1] }}>Imóveis no Rio.</motion.span>
            <motion.span initial={reduceMotion ? false : { opacity: 0, y: 70, rotate: -2 }} animate={{ opacity: 1, y: 0, rotate: 0 }} transition={{ duration: 0.6, delay: 0.16, ease: [0.16, 1, 0.3, 1] }}>Atendimento</motion.span>
            <motion.span initial={reduceMotion ? false : { opacity: 0, y: 70, rotate: 3 }} animate={{ opacity: 1, y: 0, rotate: 0 }} transition={{ duration: 0.6, delay: 0.24, ease: [0.16, 1, 0.3, 1] }}><em>pelo dono.</em></motion.span>
          </h1>
          <motion.p className="hero__lead" initial={reduceMotion ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.36 }}>Administração, compra e venda, avaliação e jurídico imobiliário. Direto com quem entende do seu patrimônio.</motion.p>
          <motion.div className="hero-actions" initial={reduceMotion ? false : { opacity: 0, y: 24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, delay: 0.43 }}><Link className="button button--signal" to="/imoveis">Encontrar meu imóvel <span aria-hidden="true">↗</span></Link><Link className="text-link" to="/sobre">Conhecer o escritório <span aria-hidden="true">→</span></Link></motion.div>
          <motion.div className="hero-signature" initial={reduceMotion ? false : { opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: 0.45, delay: 0.5 }}><strong>53</strong><span>anos de relações<br />construídas no Rio</span></motion.div>
        </div>
      </motion.div>
      <div className="hero-collage__photos" aria-label="Imóveis e pessoas da Castelo Branco">
        {cards.map((card, index) => {
          const listing = findListing(card.id)!;
          return (
            <motion.figure
              key={card.id}
              className={`hero-photo ${card.className}`}
              style={{ y: parallax ? (photoY[index] ?? 0) : 0 }}
              initial={reduceMotion ? false : { opacity: 0, scale: 0.78, rotate: card.rotation * 2.2 }}
              animate={{ opacity: 1, scale: 1, rotate: card.rotation }}
              whileHover={{ scale: 1.06, rotate: 0 }}
              transition={{ duration: 0.65, delay: 0.2 + index * 0.09, ease: [0.16, 1, 0.3, 1] }}
            >
              <img src={`/assets/listings/${card.id}.webp`} alt={listing.alt} width="900" height="1200" fetchPriority={index === 0 ? 'high' : 'auto'} decoding="async" />
              <figcaption><span>{card.position}</span>{card.caption}</figcaption>
            </motion.figure>
          );
        })}
        <motion.figure className="hero-photo hero-photo--four" style={{ y: parallax ? yFour : 0 }} initial={reduceMotion ? false : { opacity: 0, scale: 0.78, rotate: -14 }} animate={{ opacity: 1, scale: 1, rotate: -6 }} whileHover={{ scale: 1.06, rotate: 0 }} transition={{ duration: 0.65, delay: 0.47, ease: [0.16, 1, 0.3, 1] }}>
          <img src="/assets/team/leonardo.webp" alt="Leonardo Castelo Branco, advogado, engenheiro e perito avaliador" width="720" height="900" decoding="async" />
          <figcaption><span>04</span>Atendimento direto</figcaption>
        </motion.figure>
      </div>
    </div>
  );
}
