import { motion, useReducedMotion } from 'motion/react';
import { Seo } from '../components/Seo';
import { ContactBand } from '../components/ContactBand';
import { PageHero } from '../components/PageHero';
import { team } from '../site.config';

export function TeamPage() {
  const reduceMotion = useReducedMotion();
  return (
    <>
      <Seo title="Equipe | Castelo Branco Imóveis" />
      <PageHero eyebrow="Pessoas, não uma central" title="Quem faz" accent="o trabalho." description="Advocacia, engenharia, avaliação, vendas e locação. Conheça as qualificações de quem atende diretamente cada cliente." watermark="GENTE" />
      <section className="section team-section"><div className="container team-grid">{team.map((member, index) => <motion.article className="team-member" id={`person-${member.slug}`} key={member.slug} initial={reduceMotion ? false : { opacity: 0, y: 60, rotate: index % 2 === 0 ? -2 : 2 }} whileInView={{ opacity: 1, y: 0, rotate: 0 }} viewport={{ once: true, amount: 0.22 }} transition={{ duration: 0.65, ease: [0.16, 1, 0.3, 1] }}><motion.figure whileHover={reduceMotion ? {} : { scale: 0.98, rotate: index % 2 === 0 ? -1 : 1 }}><img src={`/assets/team/${member.slug}.webp`} alt={`Retrato de ${member.name}`} width="720" height="900" loading={index < 2 ? 'eager' : 'lazy'} decoding="async" /></motion.figure><div><p className="team-member__number">{String(index + 1).padStart(2, '0')}</p><h2>{member.name}</h2><p className="team-member__role">{member.role}</p><ul>{member.qualifications.map((qualification) => <li key={qualification}>{qualification}</li>)}</ul></div></motion.article>)}</div></section>
      <ContactBand />
    </>
  );
}
