import { useRef } from 'react';
import { Link } from 'react-router-dom';
import { motion, useReducedMotion, useScroll, useTransform } from 'motion/react';
import { siteConfig } from '../site.config';

export function ContactBand() {
  const section = useRef<HTMLElement>(null);
  const reduceMotion = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: section, offset: ['start end', 'end start'] });
  const titleY = useTransform(scrollYProgress, [0, 1], [90, -50]);
  const contentY = useTransform(scrollYProgress, [0, 1], [45, -25]);

  return (
    <section ref={section} className="contact-finale" aria-labelledby="contact-band-title">
      <div className="contact-finale__watermark" aria-hidden="true">FALE</div>
      <div className="container contact-finale__inner">
        <p className="eyebrow">Do outro lado, uma pessoa</p>
        <motion.h2 id="contact-band-title" style={{ y: reduceMotion ? 0 : titleY }} initial={reduceMotion ? false : { opacity: 0, rotate: -2 }} whileInView={{ opacity: 1, rotate: 0 }} viewport={{ once: true, amount: 0.35 }} transition={{ duration: 0.65, ease: [0.16, 1, 0.3, 1] }}>Fale com<br /><em>quem faz.</em></motion.h2>
        <motion.div className="contact-finale__body" style={{ y: reduceMotion ? 0 : contentY }}>
          <p>Administração, avaliação, compra e venda. Conte o que precisa: o dono ou o gerente responde, sem central telefônica e sem robô.</p>
          <motion.div whileHover={reduceMotion ? {} : { scale: 1.025, rotate: -1 }}><Link className="contact-finale__cta" to="/contato"><span>Falar com o escritório</span><strong aria-hidden="true">↗</strong></Link></motion.div>
        </motion.div>
        <div className="contact-finale__channels"><a href={siteConfig.phoneHref}><span>Telefone</span>{siteConfig.phoneDisplay}</a><a href={`mailto:${siteConfig.email}`}><span>Email</span>{siteConfig.email}</a><p><span>Escritório</span>Copacabana · Rio de Janeiro</p></div>
      </div>
    </section>
  );
}
