import { useEffect, useRef, useState, type ReactNode } from 'react';
import { NavLink } from 'react-router-dom';
import { motion, useReducedMotion } from 'motion/react';
import { siteConfig } from '../site.config';
import { SelectionDrawer } from './SelectionDrawer';

interface LayoutProps {
  children: ReactNode;
  favoritesCount: number;
  onOpenSelection: () => void;
}

export function Layout({ children, favoritesCount, onOpenSelection }: LayoutProps) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [compact, setCompact] = useState(false);
  const menuButton = useRef<HTMLButtonElement>(null);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    const update = () => setCompact(window.scrollY > 48);
    update();
    window.addEventListener('scroll', update, { passive: true });
    return () => window.removeEventListener('scroll', update);
  }, []);

  useEffect(() => {
    if (!menuOpen) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const close = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      setMenuOpen(false);
      menuButton.current?.focus();
    };
    document.addEventListener('keydown', close);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener('keydown', close);
    };
  }, [menuOpen]);

  return (
    <>
      <a className="skip-link" href="#conteudo">Pular para o conteúdo</a>
      <motion.header className={`site-header ${compact ? 'is-compact' : ''} ${menuOpen ? 'menu-is-open' : ''}`} initial={reduceMotion ? false : { opacity: 0, y: -24 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}>
        <div className="header__inner">
          <NavLink className="brand" to="/" aria-label="Castelo Branco Imóveis — início"><img className="brand__logo" src="/assets/logo.png" alt="Castelo Branco Imóveis" width="1686" height="1020" /><span className="brand__descriptor">Copacabana<br />desde 1973</span></NavLink>
          <nav id="main-nav" className={menuOpen ? 'main-nav is-open' : 'main-nav'} aria-label="Navegação principal">
            <div className="main-nav__links">{siteConfig.nav.map((item, index) => <NavLink key={item.to} to={item.to} end={item.to === '/'} className={({ isActive }) => isActive ? 'is-active' : undefined} onClick={() => setMenuOpen(false)}><span className="main-nav__number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span><span>{item.label}</span></NavLink>)}</div>
            <div className="main-nav__meta"><p>Conversa direta</p><a href={siteConfig.phoneHref}>{siteConfig.phoneDisplay}</a><a href={`mailto:${siteConfig.email}`}>{siteConfig.email}</a><address>{siteConfig.address}</address></div>
          </nav>
          <div className="header-actions">
            <button className="selection-trigger" type="button" aria-haspopup="dialog" aria-label={`Abrir minha seleção de imóveis, ${favoritesCount} guardados`} onClick={onOpenSelection}><span className="selection-trigger__label">Minha seleção</span><strong aria-label={`${favoritesCount} imóveis favoritos`}>{favoritesCount}</strong></button>
            <button ref={menuButton} className="menu-toggle" type="button" aria-expanded={menuOpen} aria-controls="main-nav" aria-label={menuOpen ? 'Fechar menu' : 'Abrir menu'} onClick={() => setMenuOpen((open) => !open)}><span className="menu-toggle__text">{menuOpen ? 'Fechar' : 'Menu'}</span><span className="menu-toggle__line"></span><span className="menu-toggle__line"></span></button>
          </div>
        </div>
      </motion.header>
      <main id="conteudo">{children}</main>
      <footer className="site-footer">
        <div className="container footer__grid">
          <div><NavLink className="footer__brand" to="/" aria-label="Castelo Branco Imóveis — início"><img className="footer__logo" src="/assets/logo.png" alt="Castelo Branco Imóveis" width="1686" height="1020" /></NavLink><p>Atendimento humano e conhecimento imobiliário desde 1973.</p></div>
          <div><p className="footer__label">Conversa direta</p><a href={siteConfig.phoneHref}>{siteConfig.phoneDisplay}</a><a href={`mailto:${siteConfig.email}`}>{siteConfig.email}</a></div>
          <div><p className="footer__label">Escritório</p><address>{siteConfig.address}</address></div>
          <div><p className="footer__label">Navegue</p><NavLink to="/imoveis">Imóveis à venda</NavLink><NavLink to="/locacao">Administração e locação</NavLink><NavLink to="/sobre">Nossa história</NavLink></div>
        </div>
        <div className="container footer__bottom"><span>© 2026 Castelo Branco Imóveis</span><a href={siteConfig.instagram} target="_blank" rel="noopener noreferrer">@imoveiscastelobranco<span className="visually-hidden">, abre em nova janela</span></a></div>
      </footer>
      <SelectionDrawer />
    </>
  );
}
