import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { AnimatePresence, motion, useMotionValueEvent, useReducedMotion, useScroll } from 'motion/react';
import { featuredListings } from '../data/listings';
import { useFavoritesContext } from '../hooks/FavoritesContext';
import type { Listing } from '../types';

function PropertyScene({ listing, index, staticLayout = false }: { listing: Listing; index: number; staticLayout?: boolean }) {
  const { favorites, toggleFavorite } = useFavoritesContext();
  const isFavorite = favorites.has(listing.id);
  const longTitle = listing.title.length > 38;

  return (
    <article className={`property-scene ${staticLayout ? 'property-scene--static' : ''}`} aria-label={`Imóvel ${index + 1} de ${featuredListings.length}`}>
      <figure className="property-scene__media"><img src={`/assets/listings/${listing.id}.webp`} alt={listing.alt} width="900" height="1200" loading="lazy" decoding="async" /></figure>
      <div className="property-scene__content">
        <p className="eyebrow">{listing.neighborhood} · {listing.type} · {listing.id}</p>
        <h3 className={longTitle ? 'property-scene__title property-scene__title--long' : 'property-scene__title'}>{listing.title}</h3>
        <p className="property-scene__location">{listing.location} · {listing.area}</p>
        <p className="property-scene__description">{listing.description}</p>
        <p className="property-scene__price">{listing.price}</p>
        <div className="property-scene__actions"><Link className="button button--primary" to={`/imoveis/${listing.id}`}>Ver este imóvel <span aria-hidden="true">↗</span></Link><button className="property-scene__favorite" type="button" aria-pressed={isFavorite} aria-label={`${isFavorite ? 'Remover' : 'Guardar'} ${listing.title}`} onClick={() => toggleFavorite(listing.id)}>{isFavorite ? '✓ Guardado' : '+ Guardar'}</button></div>
      </div>
    </article>
  );
}

export function FeaturedResidences() {
  const section = useRef<HTMLElement>(null);
  const activeRef = useRef(0);
  const reduceMotion = useReducedMotion();
  const [desktop, setDesktop] = useState(false);
  const [active, setActive] = useState(0);
  const [direction, setDirection] = useState(1);
  const { scrollYProgress } = useScroll({ target: section, offset: ['start start', 'end end'] });
  const cinematic = desktop && !reduceMotion;
  const listing = featuredListings[active]!;

  useEffect(() => {
    const query = window.matchMedia('(min-width: 901px)');
    const update = () => setDesktop(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);

  useMotionValueEvent(scrollYProgress, 'change', (latest) => {
    if (!cinematic) return;
    const next = Math.max(0, Math.min(featuredListings.length - 1, Math.floor(latest * featuredListings.length)));
    if (next === activeRef.current) return;
    setDirection(next > activeRef.current ? 1 : -1);
    activeRef.current = next;
    setActive(next);
  });

  const heading = <div className="container property-cinema__head"><div><p className="eyebrow">Imóveis disponíveis para compra</p><h2 id="featured-title">Endereços reais.<br /><em>Informação completa.</em></h2></div><div><p>Role para atravessar os endereços. Sem setas, sem cartões, sem pressa.</p><Link className="text-link" to="/imoveis">Ver os 27 imóveis <span aria-hidden="true">↗</span></Link></div></div>;

  if (!cinematic) {
    return (
      <section ref={section} id="imoveis" className="property-cinema property-cinema--static" aria-labelledby="featured-title">
        {heading}
        <div className="container property-cinema__static-list">{featuredListings.map((item, index) => <PropertyScene key={item.id} listing={item} index={index} staticLayout />)}</div>
      </section>
    );
  }

  return (
    <section ref={section} id="imoveis" className="property-cinema property-cinema--cinematic" aria-labelledby="featured-title" style={{ height: `${featuredListings.length * 75}vh` }}>
      <div className="property-cinema__sticky">
        {heading}
        <div className="container property-cinema__window">
          <AnimatePresence mode="wait" initial={false} custom={direction}>
            <motion.div key={listing.id} className="property-cinema__transition" custom={direction} variants={{ enter: (value: number) => ({ opacity: 0, x: value > 0 ? 110 : -110 }), center: { opacity: 1, x: 0 }, exit: (value: number) => ({ opacity: 0, x: value > 0 ? -110 : 110 }) }} initial="enter" animate="center" exit="exit" transition={{ duration: 0.38, ease: [0.16, 1, 0.3, 1] }}>
              <PropertyScene listing={listing} index={active} />
            </motion.div>
          </AnimatePresence>
        </div>
        <div className="container property-cinema__footer"><span>Scroll para passear ↓</span><div className="property-cinema__steps" aria-label={`Endereço ${active + 1} de ${featuredListings.length}`}>{featuredListings.map((item, index) => <span key={item.id} className={index === active ? 'is-active' : ''} aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>)}</div></div>
      </div>
    </section>
  );
}
