import { Component, type ErrorInfo, type ReactNode } from 'react';

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('Interface error', error, info);
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback ?? (
        <section className="error-state" role="alert">
          <p className="eyebrow">Não foi possível apresentar esta área</p>
          <h2>Algo falhou ao apresentar a página.</h2>
          <p>Recarregue para tentar novamente ou use os canais de contacto do escritório.</p>
          <button className="button button--primary" type="button" onClick={() => window.location.reload()}>Recarregar</button>
        </section>
      );
    }
    return this.props.children;
  }
}
