import { useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { CatalogProperty } from '../components/CatalogProperty';
import { PageHero } from '../components/PageHero';
import { Seo } from '../components/Seo';
import { EmptyState } from '../components/States';
import { useFavoritesContext } from '../hooks/FavoritesContext';
import { listings } from '../data/listings';

export function PropertiesPage() {
  const { favorites, toggleFavorite } = useFavoritesContext();
  const [params, setParams] = useSearchParams();
  const [search, setSearch] = useState(params.get('q') || '');
  const [maxPrice, setMaxPrice] = useState(params.get('preco') || '');
  const [favoritesOnly, setFavoritesOnly] = useState(false);
  const neighborhood = params.get('bairro') || '';
  const type = params.get('tipo') || '';
  const neighborhoods = [...new Set(listings.map((listing) => listing.neighborhood))].sort();
  const types = [...new Set(listings.map((listing) => listing.type))].sort();
  const filtered = useMemo(() => {
    const terms = search.toLocaleLowerCase('pt-BR').split(/\s+/).filter(Boolean);
    return listings.filter((listing) => {
      if (neighborhood && listing.neighborhood !== neighborhood) return false;
      if (type && listing.type !== type) return false;
      if (maxPrice && listing.price_brl > Number(maxPrice)) return false;
      if (favoritesOnly && !favorites.has(listing.id)) return false;
      const haystack = `${listing.neighborhood} ${listing.location} ${listing.type} ${listing.title} ${listing.area} ${listing.description}`.toLocaleLowerCase('pt-BR');
      return terms.every((term) => haystack.includes(term));
    });
  }, [search, maxPrice, neighborhood, type, favoritesOnly, favorites]);

  function updateFilter(name: string, value: string) {
    const next = new URLSearchParams(params);
    if (value) next.set(name, value);
    else next.delete(name);
    setParams(next, { replace: true });
  }

  function reset() {
    setSearch('');
    setMaxPrice('');
    setFavoritesOnly(false);
    setParams({}, { replace: true });
  }

  return (
    <>
      <Seo title="Imóveis à venda | Castelo Branco Imóveis" />
      <PageHero eyebrow="Compra e venda" title="Imóveis para" accent="escolher com calma." description="Pesquise por bairro, tipo, preço ou texto. A disponibilidade e os valores são confirmados diretamente com o escritório." watermark="MORAR" />
      <section className="section catalog-section"><div className="container">
        <form className="catalog-filters" onSubmit={(event) => event.preventDefault()} aria-label="Filtros do catálogo">
          <div className="filter-field"><label htmlFor="neighborhood-filter">Bairro</label><select id="neighborhood-filter" value={neighborhood} onChange={(event) => updateFilter('bairro', event.target.value)}><option value="">Todos</option>{neighborhoods.map((value) => <option key={value} value={value}>{value}</option>)}</select></div>
          <div className="filter-field"><label htmlFor="type-filter">Tipo</label><select id="type-filter" value={type} onChange={(event) => updateFilter('tipo', event.target.value)}><option value="">Todos</option>{types.map((value) => <option key={value} value={value}>{value}</option>)}</select></div>
          <div className="filter-field"><label htmlFor="price-filter">Preço máximo</label><input id="price-filter" type="number" min="0" step="50000" value={maxPrice} onChange={(event) => setMaxPrice(event.target.value)} placeholder="Sem limite" /></div>
          <div className="filter-field"><label htmlFor="catalog-search">Pesquisar</label><input id="catalog-search" type="search" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Rua, área ou característica" /></div>
          <div className="filter-actions"><button className="text-link" type="button" onClick={reset}>Limpar</button><button className="text-link" type="button" aria-pressed={favoritesOnly} onClick={() => setFavoritesOnly((value) => !value)}>Só favoritos</button></div>
        </form>
        <p id="catalog-count" className="catalog-count" aria-live="polite">{filtered.length} {filtered.length === 1 ? 'imóvel' : 'imóveis'}</p>
        {filtered.length === 0 ? <EmptyState onReset={reset} /> : <div className="catalog-property-list">{filtered.map((listing, index) => <CatalogProperty key={listing.id} listing={listing} index={index} favorite={favorites.has(listing.id)} onToggleFavorite={toggleFavorite} />)}</div>}
      </div></section>
    </>
  );
}
