import { useState, type FormEvent } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { HeroCollage } from '../components/HeroCollage';
import { FactsCollage } from '../components/FactsCollage';
import { ServicesStory } from '../components/ServicesStory';
import { TeamDirectory } from '../components/TeamDirectory';
import { FeaturedResidences } from '../components/FeaturedResidences';
import { ContactBand } from '../components/ContactBand';
import { Seo } from '../components/Seo';
import { listings } from '../data/listings';
import { faq } from '../site.config';

export function HomePage() {
  const navigate = useNavigate();
  const [neighborhood, setNeighborhood] = useState('');
  const [type, setType] = useState('');

  function submitSearch(event: FormEvent) {
    event.preventDefault();
    const params = new URLSearchParams();
    if (neighborhood) params.set('bairro', neighborhood);
    if (type) params.set('tipo', type);
    navigate(`/imoveis${params.size ? `?${params}` : ''}`);
  }

  const neighborhoods = [...new Set(listings.map((listing) => listing.neighborhood))].sort();
  const types = [...new Set(listings.map((listing) => listing.type))].sort();

  return (
    <>
      <Seo title="Imobiliária em Copacabana | Castelo Branco Imóveis" />
      <section className="original-hero" aria-labelledby="hero-title">
        <div className="container original-hero__grid"><HeroCollage /></div>
        <div className="container">
          <form className="property-search" onSubmit={submitSearch} aria-label="Encontrar imóveis">
            <div className="property-search__title"><strong>Encontre um imóvel no Rio</strong></div>
            <div className="filter-field"><label htmlFor="hero-neighborhood">Bairro</label><select id="hero-neighborhood" value={neighborhood} onChange={(event) => setNeighborhood(event.target.value)}><option value="">Todos os bairros</option>{neighborhoods.map((value) => <option key={value} value={value}>{value}</option>)}</select></div>
            <div className="filter-field"><label htmlFor="hero-type">Tipo de imóvel</label><select id="hero-type" value={type} onChange={(event) => setType(event.target.value)}><option value="">Todos os tipos</option>{types.map((value) => <option key={value} value={value}>{value}</option>)}</select></div>
            <button className="button button--primary" type="submit">Buscar imóveis <span aria-hidden="true">→</span></button>
          </form>
        </div>
      </section>

      <FactsCollage />

      <ServicesStory />

      <TeamDirectory />

      <FeaturedResidences />

      <section className="history-band" aria-labelledby="history-band-title"><div className="container history-band__grid"><p className="eyebrow">Nossa história</p><h2 id="history-band-title">Da Rua Santa Clara, em 1973, à Avenida Nossa Senhora de Copacabana.</h2><div><p>Um negócio iniciado pelo advogado Francisco José Castelo Branco, consolidado com Vera Lúcia Castelo Branco e ampliado pela formação jurídica e de engenharia de Leonardo.</p><Link className="text-link" to="/sobre">Ler a história completa <span aria-hidden="true">→</span></Link></div></div></section>

      <section id="faq" className="section faq" aria-labelledby="faq-title"><div className="container faq__grid"><div><p className="eyebrow">Respostas diretas</p><h2 id="faq-title">Antes de falar<br />com o escritório.</h2></div><div className="faq__list">{faq.map((item) => <details key={item.question}><summary className="faq__question">{item.question}</summary><p>{item.answer}</p></details>)}</div></div></section>
      <ContactBand />
    </>
  );
}
