import { useEffect } from 'react';
import { AnimatePresence, MotionConfig, motion, useReducedMotion } from 'motion/react';
import { Route, Routes, useLocation } from 'react-router-dom';
import { ErrorBoundary } from './components/ErrorBoundary';
import { Layout } from './components/Layout';
import { FavoritesProvider, useFavoritesContext } from './hooks/FavoritesContext';
import { HomePage } from './pages/HomePage';
import { PropertiesPage } from './pages/PropertiesPage';
import { PropertyDetailPage } from './pages/PropertyDetailPage';
import { RentalPage } from './pages/RentalPage';
import { AboutPage } from './pages/AboutPage';
import { TeamPage } from './pages/TeamPage';
import { ContactPage } from './pages/ContactPage';
import { NotFoundPage } from './pages/NotFoundPage';

function ApplicationShell() {
  const { count, openSelection } = useFavoritesContext();
  const location = useLocation();
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    if (location.hash) {
      const frame = requestAnimationFrame(() => document.getElementById(location.hash.slice(1))?.scrollIntoView());
      return () => cancelAnimationFrame(frame);
    }
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, [location.pathname, location.hash]);

  return (
    <ErrorBoundary><Layout favoritesCount={count} onOpenSelection={openSelection}>
      <AnimatePresence mode="wait" initial={false}>
        <motion.div key={location.pathname} className="route-view" initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -10 }} transition={{ duration: reduceMotion ? 0.1 : 0.24, ease: [0.16, 1, 0.3, 1] }}>
          <Routes location={location}>
            <Route path="/" element={<HomePage />} /><Route path="/imoveis" element={<PropertiesPage />} /><Route path="/imoveis/:id" element={<PropertyDetailPage />} /><Route path="/locacao" element={<RentalPage />} /><Route path="/sobre" element={<AboutPage />} /><Route path="/equipe" element={<TeamPage />} /><Route path="/contato" element={<ContactPage />} /><Route path="*" element={<NotFoundPage />} />
          </Routes>
        </motion.div>
      </AnimatePresence>
    </Layout></ErrorBoundary>
  );
}

export function App() {
  return <MotionConfig reducedMotion="user"><FavoritesProvider><ApplicationShell /></FavoritesProvider></MotionConfig>;
}
