export function LoadingState({ label = 'Carregando imóveis' }: { label?: string }) {
  return (
    <div className="loading-state" role="status" aria-live="polite">
      <span className="visually-hidden">{label}</span>
      <div className="skeleton skeleton--image" />
      <div className="skeleton skeleton--line" />
      <div className="skeleton skeleton--line skeleton--short" />
    </div>
  );
}

export function EmptyState({ onReset }: { onReset: () => void }) {
  return (
    <section className="empty-state">
      <p className="eyebrow">Nenhum imóvel encontrado</p>
      <h2>Não há resultados com estes filtros.</h2>
      <p>Amplie o bairro, o tipo ou o preço máximo para voltar a ver o catálogo.</p>
      <button className="button button--primary" type="button" onClick={onReset}>Limpar filtros</button>
    </section>
  );
}

export function ErrorState({ onRetry }: { onRetry: () => void }) {
  return (
    <section className="error-state" role="alert">
      <p className="eyebrow">Não foi possível carregar</p>
      <h2>O catálogo não respondeu.</h2>
      <p>Tente novamente. Se o problema continuar, entre em contato com o escritório.</p>
      <button className="button button--primary" type="button" onClick={onRetry}>Tentar novamente</button>
    </section>
  );
}
