import { useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { useFavoritesContext } from '../hooks/FavoritesContext';
import { findListing } from '../data/listings';

export function SelectionDrawer() {
  const { favorites, isOpen, closeSelection, toggleFavorite } = useFavoritesContext();
  const dialog = useRef<HTMLDialogElement>(null);
  const closeButton = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!isOpen || !dialog.current) return;
    const previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const previousOverflow = document.body.style.overflow;
    dialog.current.showModal();
    closeButton.current?.focus();
    document.body.style.overflow = 'hidden';

    return () => {
      document.body.style.overflow = previousOverflow;
      if (dialog.current?.open) dialog.current.close();
      previousFocus?.focus();
    };
  }, [isOpen]);

  if (!isOpen) return null;
  const selected = [...favorites].map(findListing).filter((listing): listing is NonNullable<ReturnType<typeof findListing>> => Boolean(listing));

  return (
    <dialog ref={dialog} className="selection-drawer" aria-labelledby="selection-title" onCancel={(event) => { event.preventDefault(); closeSelection(); }}>
      <div className="selection-drawer__head">
        <div><p className="eyebrow">Guardado neste dispositivo</p><h2 id="selection-title">Minha seleção</h2></div>
        <button ref={closeButton} className="icon-button" type="button" aria-label="Fechar minha seleção" onClick={closeSelection}>×</button>
      </div>
      <p className="selection-drawer__intro">Reúna os imóveis que quer discutir com o escritório. A seleção fica apenas neste navegador.</p>
      <div className="selection-items">
        {selected.map((listing) => (
          <article key={listing.id} className="selection-item">
            <img src={`/assets/listings/${listing.id}.webp`} alt={listing.alt} width="120" height="150" loading="lazy" />
            <div><h3>{listing.title}</h3><p>{listing.location} · {listing.area}</p><p>{listing.price}</p><button type="button" onClick={() => toggleFavorite(listing.id)}>Remover</button></div>
          </article>
        ))}
      </div>
      {selected.length === 0 && <p className="selection-empty">Ainda não há imóveis na sua seleção. Use “Guardar” nos cartões para começar.</p>}
      <Link className="button button--primary" to="/contato" onClick={closeSelection}>Conversar sobre a seleção</Link>
    </dialog>
  );
}
