import { motion, useReducedMotion } from 'motion/react';

export function PageHero({ eyebrow, title, accent, description, watermark }: { eyebrow: string; title: string; accent: string; description: string; watermark: string }) {
  const reduceMotion = useReducedMotion();
  const item = (delay: number): { initial: false | { opacity: number; y: number }; animate: { opacity: number; y: number }; transition: { duration: number; delay: number } } => ({ initial: reduceMotion ? false : { opacity: 0, y: 45 }, animate: { opacity: 1, y: 0 }, transition: { duration: 0.55, delay } });

  return (
    <section className="internal-hero" aria-labelledby="page-title">
      <div className="internal-hero__watermark" aria-hidden="true">{watermark}</div>
      <div className="container internal-hero__grid">
        <div><motion.p className="eyebrow" {...item(0)}>{eyebrow}</motion.p><h1 id="page-title"><motion.span {...item(0.08)}>{title}</motion.span><motion.em {...item(0.16)}>{accent}</motion.em></h1></div>
        <motion.p className="internal-hero__lead" {...item(0.26)}>{description}</motion.p>
      </div>
    </section>
  );
}
