import { Link, useParams } from 'react-router-dom';
import { motion, useReducedMotion } from 'motion/react';
import { Seo } from '../components/Seo';
import { ContactBand } from '../components/ContactBand';
import { findListing } from '../data/listings';
import { useFavoritesContext } from '../hooks/FavoritesContext';

export function PropertyDetailPage() {
  const { id } = useParams();
  const listing = findListing(id);
  const { favorites, toggleFavorite } = useFavoritesContext();
  const reduceMotion = useReducedMotion();

  if (!listing) return <section className="page-hero"><div className="container narrow-content"><Seo title="Imóvel não encontrado | Castelo Branco" /><p className="eyebrow">Catálogo</p><h1>Este imóvel não está no catálogo.</h1><p className="hero__lead">O endereço pode ter sido alterado ou o imóvel já não estar disponível.</p><Link className="button button--primary" to="/imoveis">Voltar aos imóveis</Link></div></section>;

  const isFavorite = favorites.has(listing.id);
  return (
    <>
      <Seo title={`${listing.title} | Castelo Branco Imóveis`} description={`${listing.type} em ${listing.neighborhood}, ${listing.area}. ${listing.price}. Consulte a Castelo Branco Imóveis.`} />
      <section className="property-detail" aria-labelledby="property-title"><div className="container property-detail__grid">
        <motion.figure className="property-detail__media" initial={reduceMotion ? false : { opacity: 0, scale: 0.94, rotate: -2 }} animate={{ opacity: 1, scale: 1, rotate: 0 }} transition={{ duration: 0.65, ease: [0.16, 1, 0.3, 1] }}><img src={`/assets/listings/${listing.id}.webp`} alt={listing.alt} width="900" height="1200" fetchPriority="high" /></motion.figure>
        <motion.div className="property-detail__content" initial={reduceMotion ? false : { opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.55, delay: 0.12 }}>
          <Link className="text-link" to="/imoveis">← Voltar ao catálogo</Link><p className="eyebrow">{listing.neighborhood} · {listing.type} · {listing.id}</p><h1 id="property-title">{listing.title}</h1><p className="property-detail__location">{listing.location}</p>
          <dl className="property-specs"><div><dt>Área</dt><dd>{listing.area}</dd></div><div><dt>Preço</dt><dd>{listing.price}</dd></div><div><dt>Bairro</dt><dd>{listing.neighborhood}</dd></div></dl>
          <p className="property-detail__description">{listing.description}</p><p className="property-detail__note">Disponibilidade, valores e condições são confirmados diretamente com o escritório.</p>
          <div className="hero-actions"><Link className="button button--signal" to={`/contato?imovel=${listing.id}`}>Consultar este imóvel <span aria-hidden="true">→</span></Link><button className="button button--outline" type="button" aria-pressed={isFavorite} onClick={() => toggleFavorite(listing.id)}>{isFavorite ? 'Remover da seleção' : 'Guardar na seleção'}</button></div>
        </motion.div>
      </div></section>
      <ContactBand />
    </>
  );
}
