import { useState, type FormEvent } from 'react';
import { useSearchParams } from 'react-router-dom';
import { motion, useReducedMotion } from 'motion/react';
import { Seo } from '../components/Seo';
import { PageHero } from '../components/PageHero';
import { findListing } from '../data/listings';
import { siteConfig } from '../site.config';
import type { ContactFormValues } from '../types';

type SubmitStatus = 'idle' | 'submitting' | 'success' | 'error';

export function ContactPage() {
  const [params] = useSearchParams();
  const reduceMotion = useReducedMotion();
  const listing = findListing(params.get('imovel') || undefined);
  const rental = params.get('assunto') === 'locacao';
  const initialMessage = listing ? `Olá, gostaria de informações sobre o imóvel ${listing.id} — ${listing.title}.` : rental ? 'Olá, gostaria de conversar sobre administração ou locação de um imóvel.' : '';
  const [status, setStatus] = useState<SubmitStatus>('idle');
  const [emailHref, setEmailHref] = useState('');

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const values: ContactFormValues = { name: String(data.get('name') || ''), phone: String(data.get('phone') || ''), email: String(data.get('email') || ''), message: String(data.get('message') || '') };
    const href = `mailto:${siteConfig.email}?subject=${encodeURIComponent(listing ? `Consulta sobre ${listing.id}` : rental ? 'Administração e locação' : 'Contato pelo site')}&body=${encodeURIComponent(`${values.message}\n\nNome: ${values.name}\nTelefone: ${values.phone || 'Não informado'}\nEmail: ${values.email}`)}`;
    setEmailHref(href);
    setStatus('submitting');
    try {
      const response = await fetch('/api/contact', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(values) });
      if (!response.ok) throw new Error('contact_request_failed');
      setStatus('success');
    } catch { setStatus('error'); }
  }

  return (
    <>
      <Seo title="Contato | Castelo Branco Imóveis" />
      <PageHero eyebrow="Conversa direta" title="Fale com" accent="o escritório." description="Conte o que precisa. O dono ou o gerente responde, sem central telefônica e sem robô." watermark="FALE" />
      <section className="section contact-section"><div className="container contact-grid">
        <motion.div className="contact-details" initial={reduceMotion ? false : { opacity: 0, y: 40 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.3 }}><p className="eyebrow">Canais de atendimento</p><h2>Escolha como conversar.</h2><dl><div><dt>Telefone</dt><dd><a href={siteConfig.phoneHref}>{siteConfig.phoneDisplay}</a></dd></div><div><dt>Email</dt><dd><a href={`mailto:${siteConfig.email}`}>{siteConfig.email}</a></dd></div><div><dt>Escritório</dt><dd>{siteConfig.address}</dd></div><div><dt>Instagram</dt><dd><a href={siteConfig.instagram} target="_blank" rel="noopener noreferrer">@imoveiscastelobranco<span className="visually-hidden">, abre em nova janela</span></a></dd></div></dl></motion.div>
        <motion.form className="contact-form" onSubmit={submit} initial={reduceMotion ? false : { opacity: 0, y: 50, rotate: 1 }} whileInView={{ opacity: 1, y: 0, rotate: 0 }} viewport={{ once: true, amount: 0.2 }} transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}>
          <div><p className="eyebrow">Mensagem</p><h2>{listing ? `Sobre ${listing.id}` : 'Como podemos ajudar?'}</h2></div>
          <div className="form-field"><label htmlFor="contact-name">Nome</label><input id="contact-name" name="name" type="text" autoComplete="name" minLength={2} maxLength={120} required /></div>
          <div className="form-field"><label htmlFor="contact-phone">Telefone <span>(opcional)</span></label><input id="contact-phone" name="phone" type="tel" autoComplete="tel" maxLength={30} /></div>
          <div className="form-field"><label htmlFor="contact-email">Email</label><input id="contact-email" name="email" type="email" autoComplete="email" maxLength={160} required /></div>
          <div className="form-field"><label htmlFor="contact-message">Mensagem</label><textarea id="contact-message" name="message" rows={6} minLength={10} maxLength={4000} defaultValue={initialMessage} required /></div>
          <p className="form-privacy">O formulário registra a mensagem na base local do site. Nada é enviado por email automaticamente; você confirma esse passo no seu aplicativo de email.</p>
          <button className="button button--signal" type="submit" disabled={status === 'submitting'}>{status === 'submitting' ? 'Registrando…' : 'Registrar e preparar email'} <span aria-hidden="true">→</span></button>
          {status === 'success' && <div className="form-feedback form-feedback--success" role="status"><p>Mensagem registrada. Para enviá-la ao escritório, abra agora o email preparado.</p><a className="text-link" href={emailHref}>Abrir email preparado <span aria-hidden="true">↗</span></a></div>}
          {status === 'error' && <div className="form-feedback form-feedback--error" role="alert"><p>Não foi possível registrar a mensagem. Você ainda pode preparar o email e enviá-lo pelo seu aplicativo.</p><a className="text-link" href={emailHref}>Preparar email sem registro <span aria-hidden="true">↗</span></a></div>}
        </motion.form>
      </div></section>
    </>
  );
}
