import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { motion, useReducedMotion, useScroll, useTransform } from 'motion/react';
import { services } from '../site.config';
import type { Service } from '../types';

function ServiceScene({ service, index, active }: { service: Service; index: number; active: boolean }) {
  const scene = useRef<HTMLElement>(null);
  const reduceMotion = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: scene, offset: ['start end', 'end start'] });
  const imageY = useTransform(scrollYProgress, [0, 1], [110, -110]);
  const imageScale = useTransform(scrollYProgress, [0, 0.5, 1], [1.08, 1, 1.05]);
  const contentY = useTransform(scrollYProgress, [0, 1], [60, -60]);
  const numberY = useTransform(scrollYProgress, [0, 1], [index % 2 === 0 ? 70 : -70, 0]);
  const number = String(index + 1).padStart(2, '0');
  const route = index % 2 === 0 ? 'M30 560C260 400 390 610 610 420C790 260 960 300 1170 130' : 'M30 150C260 330 430 70 620 260C820 460 970 470 1170 560';

  return (
    <article ref={scene} className={`service-scene service-scene--${index + 1}`} aria-labelledby={`service-${service.slug}`}>
      <motion.span className="service-scene__number" aria-hidden="true" style={{ y: active ? numberY : 0 }} initial={reduceMotion ? false : { opacity: 0 }} whileInView={{ opacity: 0.09 }} viewport={{ once: true, amount: 0.3 }} transition={{ duration: 0.6 }}>{number}</motion.span>
      <svg className="service-scene__route" viewBox="0 0 1200 700" fill="none" aria-hidden="true">
        <motion.path d={route} stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" initial={reduceMotion ? false : { pathLength: 0, opacity: 0 }} whileInView={{ pathLength: 1, opacity: 0.35 }} viewport={{ once: true, amount: 0.35 }} transition={{ duration: 1, ease: [0.16, 1, 0.3, 1] }} />
      </svg>
      <motion.figure className="service-scene__media" style={{ y: active ? imageY : 0 }} initial={reduceMotion ? false : { opacity: 0, rotate: index % 2 === 0 ? -4 : 4 }} whileInView={{ opacity: 1, rotate: 0 }} viewport={{ once: true, amount: 0.25 }} transition={{ duration: 0.75, ease: [0.16, 1, 0.3, 1] }}>
        <motion.img src={service.image} alt={service.alt} width="1400" height="933" loading="lazy" decoding="async" style={{ scale: active ? imageScale : 1 }} />
      </motion.figure>
      <motion.div className="service-scene__content" style={{ y: active ? contentY : 0 }} initial={reduceMotion ? false : { opacity: 0 }} whileInView={{ opacity: 1 }} viewport={{ once: true, amount: 0.35 }} transition={{ duration: 0.55, delay: 0.15 }}>
        <p className="eyebrow">{service.subtitle}</p>
        <h3 id={`service-${service.slug}`}>{service.title}</h3>
        <p>{service.description}</p>
        <Link className="text-link" to={service.href}>{service.label} <span aria-hidden="true">↗</span></Link>
      </motion.div>
    </article>
  );
}

export function ServicesStory() {
  const reduceMotion = useReducedMotion();
  const [desktop, setDesktop] = useState(false);

  useEffect(() => {
    const query = window.matchMedia('(min-width: 901px)');
    const update = () => setDesktop(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);

  return (
    <section id="servicos" className="services-story" aria-labelledby="services-title">
      <div className="container services-story__intro">
        <p className="eyebrow">Áreas de atuação</p>
        <motion.h2 id="services-title" initial={reduceMotion ? false : { opacity: 0, y: 80, rotate: -3 }} whileInView={{ opacity: 1, y: 0, rotate: 0 }} viewport={{ once: true, amount: 0.4 }} transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}>Cuidado<br />em cada<br /><em>metro.</em></motion.h2>
        <motion.p initial={reduceMotion ? false : { opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.5 }} transition={{ duration: 0.55, delay: 0.2 }}>Da administração à perícia e ao inventário: conhecimento operacional, técnico e jurídico na mesma casa.</motion.p>
      </div>
      <div className="container services-story__scenes">
        {services.map((service, index) => <ServiceScene key={service.slug} service={service} index={index} active={desktop && !reduceMotion} />)}
      </div>
    </section>
  );
}
