import { motion, useReducedMotion } from 'motion/react';
import { siteConfig } from '../site.config';

const entrances = [
  { x: 90, y: -50, rotate: 12 },
  { x: -80, y: 70, rotate: -10 },
  { x: 70, y: 90, rotate: 9 },
  { x: -60, y: -80, rotate: -12 },
];

const restingRotations = [-3, 4, -2, 3];

export function FactsCollage() {
  const reduceMotion = useReducedMotion();

  return (
    <section className="facts facts-deconstructed" aria-labelledby="facts-title">
      <div className="facts__marquee" aria-hidden="true">RIO</div>
      <div className="container facts__stage">
        <p className="facts__eyebrow">Castelo Branco em números</p>
        <motion.h2 id="facts-title" className="facts__title" initial={reduceMotion ? false : { opacity: 0, y: 80, rotate: -4 }} whileInView={{ opacity: 1, y: 0, rotate: 0 }} viewport={{ once: true, amount: 0.4 }} transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}>
          O Rio é<br /><em>a nossa casa.</em>
        </motion.h2>
        <svg className="facts__line" viewBox="0 0 1200 700" fill="none" aria-hidden="true">
          <motion.path d="M40 550C260 390 370 690 600 510C790 360 940 290 1160 390" stroke="currentColor" strokeWidth="2" strokeLinecap="round" initial={reduceMotion ? false : { pathLength: 0, opacity: 0 }} whileInView={{ pathLength: 1, opacity: 0.65 }} viewport={{ once: true, amount: 0.3 }} transition={{ duration: 1.1, ease: [0.16, 1, 0.3, 1] }} />
        </svg>
        {siteConfig.facts.map((fact, index) => (
          <motion.div
            key={fact.label}
            className={`fact fact--${index + 1}`}
            initial={reduceMotion ? false : { opacity: 0, ...entrances[index] }}
            whileInView={{ opacity: 1, x: 0, y: 0, rotate: restingRotations[index] ?? 0 }}
            viewport={{ once: true, amount: 0.45 }}
            transition={{ duration: 0.65, delay: index * 0.07, ease: [0.16, 1, 0.3, 1] }}
          >
            <strong>{fact.value}</strong><span>{fact.label}</span>
          </motion.div>
        ))}
      </div>
    </section>
  );
}
