import { useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { AnimatePresence, motion, useReducedMotion, useScroll, useTransform } from 'motion/react';
import { team } from '../site.config';

export function TeamDirectory() {
  const section = useRef<HTMLElement>(null);
  const reduceMotion = useReducedMotion();
  const [active, setActive] = useState(0);
  const { scrollYProgress } = useScroll({ target: section, offset: ['start end', 'end start'] });
  const previewY = useTransform(scrollYProgress, [0, 1], [60, -60]);
  const previewRotate = useTransform(scrollYProgress, [0, 1], [-4, 4]);
  const current = team[active] ?? team[0]!;

  return (
    <section ref={section} className="team-directory" aria-labelledby="team-directory-title">
      <div className="team-directory__watermark" aria-hidden="true">GENTE</div>
      <div className="container team-directory__inner">
        <div className="team-directory__head">
          <p className="eyebrow">Equipe Castelo Branco</p>
          <motion.h2 id="team-directory-title" initial={reduceMotion ? false : { opacity: 0, y: 70, rotate: 3 }} whileInView={{ opacity: 1, y: 0, rotate: 0 }} viewport={{ once: true, amount: 0.4 }} transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}>As pessoas<br />que <em>atendem você.</em></motion.h2>
          <p>Advocacia, engenharia, corretagem, avaliação, vendas e gestão de locação. Quem atende também assina o trabalho.</p>
        </div>
        <div className="team-directory__body">
          <div className="team-directory__list" aria-label="Pessoas da equipe">
            {team.map((member, index) => (
              <motion.div key={member.slug} className={`team-directory__person ${active === index ? 'is-active' : ''}`} initial={reduceMotion ? false : { opacity: 0, y: index % 2 === 0 ? -30 : 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.5 }} transition={{ duration: 0.5, delay: index * 0.05 }} whileHover={{ x: 8 }}>
                <Link to={`/equipe#person-${member.slug}`} onMouseEnter={() => setActive(index)} onFocus={() => setActive(index)}>
                  <span className="team-directory__index">{String(index + 1).padStart(2, '0')}</span>
                  <img className="team-directory__thumb" src={`/assets/team/${member.slug}.webp`} alt="" width="720" height="900" loading="lazy" aria-hidden="true" />
                  <span className="team-directory__name"><strong>{member.name}</strong><small>{member.role}</small></span>
                  <span className="team-directory__arrow" aria-hidden="true">↗</span>
                </Link>
              </motion.div>
            ))}
          </div>
          <div className="team-directory__preview" aria-live="polite">
            <motion.div className="team-directory__preview-motion" style={{ y: reduceMotion ? 0 : previewY, rotate: reduceMotion ? 0 : previewRotate }}>
              <span className="team-directory__preview-number" aria-hidden="true">{String(active + 1).padStart(2, '0')}</span>
              <AnimatePresence mode="wait" initial={false}>
                <motion.figure key={current.slug} initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.88, rotate: -6 }} animate={{ opacity: 1, scale: 1, rotate: 0 }} exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96, rotate: 4 }} transition={{ duration: reduceMotion ? 0.1 : 0.35, ease: [0.16, 1, 0.3, 1] }}>
                  <img src={`/assets/team/${current.slug}.webp`} alt={`Retrato de ${current.name}`} width="720" height="900" loading="lazy" />
                  <figcaption><strong>{current.name}</strong><span>{current.role}</span></figcaption>
                </motion.figure>
              </AnimatePresence>
            </motion.div>
          </div>
        </div>
        <Link className="button button--light team-directory__cta" to="/equipe">Conhecer as qualificações <span aria-hidden="true">→</span></Link>
      </div>
    </section>
  );
}
