import listingsJson from '../../listings.json' with { type: 'json' };
import type { Listing } from '../types';

export const listings = listingsJson as Listing[];

export const featuredListings = listings.filter((listing) => ['CB-009', 'CB-006', 'CB-011', 'CB-017', 'CB-023', 'CB-020'].includes(listing.id));

export function findListing(id: string | undefined): Listing | undefined {
  return listings.find((listing) => listing.id === id);
}
